#!/usr/bin/env bash
cd ~/Projects/konkon-hanafuda
S="Cute chunky kemono (furry) anime game art, thick clean dark outlines, soft cel shading, warm saturated colors, all-ages, not sexualized."
G="Full body, single character centered, plain flat pure green (#00FF00) background with nothing else, no shadow on the background, no text."
tools/gen_image.sh art/raw/kon_base.png "$S $G Character: 'Kon', a small young fox yokai (kitsune) child. Anthropomorphic fox with a clear fox muzzle, bright orange fur, white muzzle, chest and tail tip, big round amber eyes, very round chubby squishy body, one huge fluffy tail. Wears a short red-and-white shrine-style happi coat tied with a thick rope belt, a small golden bell on a red cord around the neck, and a green maple-like transformation leaf on the head. Holds a fan of hanafuda cards in one paw, other paw raised cheerfully, big carefree grin. Airheaded optimistic gambler vibe." &
tools/gen_image.sh art/raw/gin_base.png "$S $G Character: 'Gin', a shrine guardian fox (komagitsune) come to life. Anthropomorphic slender fox with a clear fox muzzle, silvery white fur with pale blue-grey markings, narrow stern half-lidded eyes, a red bib (yodarekake) tied at the neck like stone fox statues at Inari shrines, holds a small scroll key in one paw, other paw on hip, exasperated deadpan expression with a sweat drop. Serious straight-man vibe. Adult-ish teen build, standing upright." &
tools/gen_image.sh art/raw/bg_den.png "Background illustration for a game, no characters, no text: the inside of a secret yokai gambling den at night in old Edo Japan. Large tatami room, a long low wooden gambling table covered with a dark green felt cloth in the center, many glowing red paper lanterns (chochin) hanging from wooden beams, shoji screens with warm light, floating blue will-o'-wisp spirit flames (onibi), scattered hanafuda cards and coins, purple night mist. Painterly anime background, rich deep reds, golds and indigo, slightly dark so UI on top stays readable. 16:9 wide composition." &
wait
